    private static readonly IntPtr _bindRequest =
        NetwApi.MethodBind("Netw", "request", 2325787334UL);

    /// <summary>
    /// Calls <paramref name="method"/> on the server and returns a
    /// <see cref="NetwPromise"/> with its return value.
    /// <code>
    /// public async void BuyShield()
    /// {
    ///     bool sold = (await Netw.Request(shop.Buy, (StringName)"shield")).AsBool();
    /// }
    ///
    /// [Rpc(MultiplayerApi.RpcMode.AnyPeer)]
    /// public Variant Buy(StringName item) =&gt; NetwPromise.FromTask(stock.Take(item));
    /// </code>
    /// <para>
    /// The method must be an RPC, as for <see cref="Netw.Rpc"/>. The promise
    /// fails at once when the node is not part of a spawned
    /// <see cref="NetwEntity"/>. The method may <c>await</c>, and the reply is
    /// sent when it returns. A method whose node is freed while it waits never
    /// replies, so the promise fails when it times out.
    /// </para>
    /// </summary>
    public static NetwPromise Request(
        Node node,
        StringName method,
        params Variant[] rest)
    {
        int total = 1 + (rest == null ? 0 : rest.Length);
        IntPtr pack = NetwThunks.ArgsNew(total);
        godot_variant slot0 =
            VariantUtils.CreateFromCallable(new Callable(node, method));
        NetwThunks.ArgsSet(pack, 0, in slot0);
        slot0.Dispose();
        for (int index = 1; index < total; index++)
        {
            godot_variant carried = rest[index - 1].CopyNativeVariant();
            NetwThunks.ArgsSet(pack, index, in carried);
            carried.Dispose();
        }
        godot_variant answered = default;
        NetwThunks.CallPack(
            _bindRequest,
            IntPtr.Zero,
            pack,
            total,
            ref answered);
        NetwThunks.ArgsFree(pack);
        NetwPromise result =
            NetwPromise.Adopt(
                NetwApi.Retained(
                    VariantUtils.ConvertToGodotObjectPtr(answered)));
        answered.Dispose();
        return result;
    }

