    /// <summary>
    /// Calls <paramref name="method"/> on every peer that can see the node, and
    /// returns a <see cref="NetwGroupPromise"/> with each return value. The
    /// promise fails at once when the node is not part of a spawned
    /// <see cref="NetwEntity"/>. This peer is asked too when the method is
    /// <c>call_local</c>, set through [annotation @GDScript.@rpc] or
    /// <see cref="NetwMemberConfig.CallLocal"/>. The method may <c>await</c>
    /// for 5 seconds, and <see cref="NetwMemberConfig.Timeout"/> sets a longer
    /// deadline.
    /// <code>
    /// public partial class SceneManager : Node
    /// {
    ///     const string Match = "res://match.tscn";
    ///
    ///     PackedScene warm;
    ///
    ///     public SceneManager()
    ///     {
    ///         Netw.ConfigureEntity(this);
    ///         Netw.ConfigureRpc(this, MethodName.PreloadLevel).Timeout(60.0);
    ///         Netw.ConfigureSpawn(this, MethodName.MakeMatch);
    ///         Netw.ConfigureSpawn(this, MethodName.MakePlayer);
    ///     }
    ///
    ///     public async void StartMatch()
    ///     {
    ///         NetwGroupPromise loads = await Netw.RequestAll(this, MethodName.PreloadLevel, Match);
    ///         if (loads.IsFailed || loads.Results.Values.Any(loaded =&gt; !loaded.AsBool()))
